//! Joining, resuming, disconnecting and leaving.

use sppy_proto::{ErrorCode, MediaStatus, NoticeAction, Participant, ParticipantId};

use super::{Effect, Member, Room};

const MAX_NICKNAME_CHARS: usize = 32;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum JoinRole {
    Host,
    Guest,
}

#[derive(Debug, Clone)]
pub struct JoinRequest {
    pub nickname: String,
    pub role: JoinRole,
    /// Generated by the I/O layer (keeps the room free of randomness).
    pub session_token: String,
}

/// Result of a successful join or resume. `effects[0]` is always the `Welcome`.
#[derive(Debug, Clone)]
pub struct Joined {
    pub participant_id: ParticipantId,
    pub effects: Vec<Effect>,
}

impl Room {
    pub fn join(&mut self, now_ms: u64, req: JoinRequest) -> Result<Joined, ErrorCode> {
        let nick = req.nickname.trim().to_owned();
        let len = nick.chars().count();
        if len == 0 || len > MAX_NICKNAME_CHARS {
            return Err(ErrorCode::InvalidRequest);
        }
        let lower = nick.to_lowercase();
        if self
            .members
            .iter()
            .any(|m| m.info.nickname.to_lowercase() == lower)
        {
            return Err(ErrorCode::NicknameTaken);
        }
        if self.members.len() >= self.config.max_participants {
            return Err(ErrorCode::RoomFull);
        }
        let pid = ParticipantId(self.next_participant_id);
        self.next_participant_id += 1;
        self.members.push(Member {
            info: Participant {
                id: pid,
                nickname: nick,
                is_host: req.role == JoinRole::Host,
                can_control: false,
                connected: true,
                status: MediaStatus::Loading,
            },
            session_token: req.session_token,
            disconnected_at: None,
        });
        let mut effects = vec![self.welcome(now_ms, pid), self.broadcast_room()];
        effects.push(Self::notice(Some(pid), NoticeAction::Joined));
        Ok(Joined {
            participant_id: pid,
            effects,
        })
    }

    pub fn resume(&mut self, now_ms: u64, session_token: &str) -> Result<Joined, ErrorCode> {
        let m = self
            .members
            .iter_mut()
            .find(|m| m.session_token == session_token)
            .ok_or(ErrorCode::SessionExpired)?;
        m.info.connected = true;
        m.disconnected_at = None;
        let pid = m.info.id;
        let effects = vec![self.welcome(now_ms, pid), self.broadcast_room()];
        Ok(Joined {
            participant_id: pid,
            effects,
        })
    }

    /// The socket dropped; keep the participant for the resume grace period.
    pub fn disconnected(&mut self, now_ms: u64, pid: ParticipantId) -> Vec<Effect> {
        let Some(m) = self.member_mut(pid) else {
            return Vec::new();
        };
        m.info.connected = false;
        m.disconnected_at = Some(now_ms);
        vec![self.broadcast_room()]
    }

    /// `Bye` or kick: remove immediately.
    pub fn leave(&mut self, _now_ms: u64, pid: ParticipantId) -> Vec<Effect> {
        if self.remove_member(pid) {
            vec![
                self.broadcast_room(),
                Self::notice(Some(pid), NoticeAction::Left),
            ]
        } else {
            Vec::new()
        }
    }

    pub(super) fn remove_member(&mut self, pid: ParticipantId) -> bool {
        let before = self.members.len();
        self.members.retain(|m| m.info.id != pid);
        self.members.len() != before
    }

    pub(super) fn expire_disconnected(&mut self, now_ms: u64) -> Vec<Effect> {
        let grace = self.config.resume_grace_ms;
        let expired: Vec<ParticipantId> = self
            .members
            .iter()
            .filter(|m| {
                m.disconnected_at
                    .is_some_and(|t| now_ms.saturating_sub(t) >= grace)
            })
            .map(|m| m.info.id)
            .collect();
        let mut effects = Vec::new();
        for pid in expired {
            effects.extend(self.leave(now_ms, pid));
        }
        effects
    }
}
